const puppeteer = require('puppeteer');
const express = require('express');
const crypto = require('crypto');
const { JSDOM } = require('jsdom');

const app = express();
app.use(express.json());

// Solidity contract PDF report generator
// Generates audit reports from contract metadata

class SolidityReportRenderer {
  constructor() {
    this.templateCache = new Map();
    this.renderQueue = [];
    this.processing = false;
  }

  // Sanitize contract names for display
  sanitizeIdentifier(name) {
    // Allow solidity-valid identifiers plus common display chars
    return name.replace(/[<>"'&]/g, (ch) => ({'<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#x27;','&':'&amp;'}[ch]));
  }

  // Build the function signature display from ABI
  buildFunctionSignature(func) {
    const params = func.inputs.map(i => `${this.sanitizeIdentifier(i.type)} ${this.sanitizeIdentifier(i.name)}`);
    return `${this.sanitizeIdentifier(func.name)}(${params.join(', ')})`;
  }

  // Encode contract metadata into HTML section
  encodeMetadataSection(metadata) {
    const compiler = this.escapeHtml(metadata.compiler || 'solc 0.8.x');
    const license = this.escapeHtml(metadata.license || 'MIT');
    return `<div class="metadata"><span class="compiler">${compiler}</span><span class="license">${license}</span></div>`;
  }

  escapeHtml(text) {
    if (typeof text !== 'string') return '';
    return text.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#x27;');
  }

  // Generate the natspec documentation section
  renderNatspecBlock(natspec) {
    if (!natspec) return '';
    const title = natspec.title ? `<h3>${this.escapeHtml(natspec.title)}</h3>` : '';
    const author = natspec.author ? `<p class="author">Author: ${this.escapeHtml(natspec.author)}</p>` : '';
    // Notice field is also escaped for safety
    const notice = natspec.notice ? `<p class="notice">${this.escapeHtml(natspec.notice)}</p>` : '';
    return `<div class="natspec">${title}${author}${notice}</div>`;
  }

  // Build vulnerability findings section
  renderFindings(findings) {
    if (!findings || findings.length === 0) return '<p>No findings.</p>';
    return findings.map((f, idx) => {
      const severity = this.encodeSeverity(f.severity);
      const desc = this.sanitizeDescription(f.description);
      const location = this.encodeLocation(f.location);
      return `<div class="finding">${severity}${desc}${location}</div>`;
    }).join('');
  }

  encodeSeverity(sev) {
    const allowed = ['Critical', 'High', 'Medium', 'Low', 'Informational'];
    const safe = allowed.includes(sev) ? sev : 'Unknown';
    return `<span class="severity severity-${safe.toLowerCase()}">${safe}</span>`;
  }

  sanitizeDescription(desc) {
    if (!desc) return '';
    return `<p>${desc.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')}</p>`;
  }

  encodeLocation(loc) {
    if (!loc) return '';
    return `<code>${loc.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')}</code>`;
  }

  // Main template assembly - combines all sections
  async assembleReport(contractData) {
    const nonce = crypto.randomBytes(16).toString('hex');
    const metadata = this.encodeMetadataSection(contractData.metadata || {});
    const natspec = this.renderNatspecBlock(contractData.natspec);
    const functions = (contractData.abi || []).filter(f => f.type === 'function');
    const funcHtml = functions.map(f => 
      `<div class="func"><code>${this.buildFunctionSignature(f)}</code></div>`
    ).join('');
    const findings = this.renderFindings(contractData.findings);

    // The source code display uses a special encoding path
    const sourceDisplay = await this.renderSourceCode(contractData.source);

    return `<!DOCTYPE html><html><head><meta charset="utf-8">
<meta http-equiv="Content-Security-Policy" content="default-src 'none'; style-src 'nonce-${nonce}'">
<style nonce="${nonce}">body{font-family:monospace;margin:2em}.finding{border:1px solid #ccc;padding:1em;margin:1em 0}.severity{font-weight:bold}.severity-critical{color:red}.severity-high{color:orange}</style>
</head><body>
<h1>Smart Contract Audit Report</h1>
${metadata}
${natspec}
<h2>Functions</h2>${funcHtml}
<h2>Findings</h2>${findings}
<h2>Source</h2>${sourceDisplay}
</body></html>`;
  }

  // Render source code with syntax highlighting
  // Uses a two-phase encode: first structural, then decorative
  async renderSourceCode(source) {
    if (!source) return '<pre>No source provided.</pre>';

    // Phase 1: structural encoding for safety
    const structuralEncoded = this.structuralEncode(source);

    // Phase 2: apply syntax highlighting (async for large files)
    const highlighted = await this.applySyntaxHighlighting(structuralEncoded);

    return `<pre class="source">${highlighted}</pre>`;
  }

  structuralEncode(text) {
    // Encode HTML entities
    return text
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;');
  }

  async applySyntaxHighlighting(encoded) {
    // Simulate async processing for large contracts
    await new Promise(resolve => setImmediate(resolve));

    // Highlight Solidity keywords by wrapping in spans
    const keywords = ['pragma', 'contract', 'function', 'modifier', 'event', 
                      'mapping', 'address', 'uint256', 'bool', 'string',
                      'public', 'private', 'internal', 'external', 'view',
                      'pure', 'payable', 'returns', 'require', 'emit'];

    let result = encoded;
    for (const kw of keywords) {
      // Word boundary replacement on already-encoded text
      const regex = new RegExp(`\\b${kw}\\b`, 'g');
      result = result.replace(regex, `<span class="kw">${kw}</span>`);
    }

    // Highlight comments: // style
    result = result.replace(/(\/{2}[^\n]*)/g, '<span class="comment">$1</span>');

    // Highlight string literals that were encoded
    result = result.replace(/(&quot;[^&]*&quot;)/g, '<span class="str">$1</span>');

    return result;
  }

  async generatePDF(contractData) {
    const html = await this.assembleReport(contractData);

    const browser = await puppeteer.launch({
      headless: 'new'
    });

    try {
      const page = await browser.newPage();
      await page.setContent(html, { waitUntil: 'networkidle0' });
      const pdf = await page.pdf({ format: 'A4', printBackground: true });
      return pdf;
    } finally {
      await browser.close();
    }
  }
}

const renderer = new SolidityReportRenderer();

app.post('/api/generate-report', async (req, res) => {
  try {
    const contractData = req.body;
    if (!contractData || typeof contractData !== 'object') {
      return res.status(400).json({ error: 'Invalid contract data' });
    }
    const pdf = await renderer.generatePDF(contractData);
    res.setHeader('Content-Type', 'application/pdf');
    res.setHeader('Content-Disposition', 'attachment; filename="audit-report.pdf"');
    res.send(pdf);
  } catch (err) {
    res.status(500).json({ error: 'Report generation failed' });
  }
});

app.listen(3000);
module.exports = { SolidityReportRenderer };
